function IconButton({icon:Icon,children,...props}){return <button {...props}><Icon size={17}/>{children}</button>}
function CreditCollection({customerId,info,reload,flash,setError}){let [amount,setAmount]=useState(''),[method,setMethod]=useState('Cash'),[busy,setBusy]=useState(false);let bills=info?.bills.filter(b=>b.duePaisa>0)||[];async function pay(receiptId){if(!amount||Number(amount)<=0){setError('Enter the amount collected.');return}setBusy(true);try{let r=await api('/customers/credit-payment','POST',{customerId,receiptId,amount,method});setAmount('');await reload();flash('Credit payment recorded. Remaining: '+M(r.remainingPaisa))}catch(e){setError(e.message)}finally{setBusy(false)}}return <div className="pos-credit"><h3>Collect customer credit</h3>{bills.length?bills.map(b=><div className="credit-line" key={b.id}><div><strong>{b.id}</strong><small>Due {M(b.duePaisa)}</small></div><input type="number" min="0.01" step="0.01" max={b.duePaisa/100} value={amount} onChange={e=>setAmount(e.target.value)} placeholder="Rs amount" aria-label="Payment amount"/><select value={method} onChange={e=>setMethod(e.target.value)} aria-label="Payment method"><option>Cash</option><option>Card</option><option>Bank transfer</option></select><button disabled={busy} onClick={()=>pay(b.id)}>Record payment</button></div>):<p>No unpaid credit bills for this customer.</p>}</div>}
function App({portal}){let[mode,setMode]=useState('loading'),[setupAvailable,setSetupAvailable]=useState(false),[password,setPassword]=useState(''),[owner,setOwner]=useState(''),[user,setUser]=useState(''),[role,setRole]=useState('admin'),[email,setEmail]=useState(''),[accounts,setAccounts]=useState([]),[accountForm,setAccountForm]=useState({role:'staff'}),[view,setView]=useState('dashboard'),[data,setData]=useState(blank),[orders,setOrders]=useState([]),[activities,setActivities]=useState([]),[customers,setCustomers]=useState([]),[customerInfo,setCustomerInfo]=useState(null),[modal,setModal]=useState(null),[form,setForm]=useState({}),[error,setError]=useState(''),[toast,setToast]=useState(''),[query,setQuery]=useState(''),[filter,setFilter]=useState('all'),[sidebar,setSidebar]=useState(false),[busy,setBusy]=useState(false),[cart,setCart]=useState({}),[scan,setScan]=useState(''),[search,setSearch]=useState(''),[bill,setBill]=useState({payment:'Cash',discount:0,tax:0,customer:'',customerId:'',redeemPoints:0,received:'',note:''}),[receipt,setReceipt]=useState(null),[camera,setCamera]=useState(false),[linkOpen,setLinkOpen]=useState(false),[adminPhone,setAdminPhone]=useState(''),[adminCode,setAdminCode]=useState(''),[adminPhoneResult,setAdminPhoneResult]=useState(null);let scanRef=useRef(),videoRef=useRef(),streamRef=useRef(),timerRef=useRef(),adminVerifier=useRef();
const flash=s=>{setToast(s);setTimeout(()=>setToast(''),3500)};
useLiveRefresh(()=>{if(mode==='ready'&&portal!=='vendor')return refresh()});
async function refresh(){let me=await api('/me');if(me.user.role==='vendor')return;let [v,o,c]=await Promise.all([api('/state'),api('/orders'),api('/customers')]);setData(v);setOrders(o.orders);setCustomers(c.customers);if(me.user.role==='admin'){let feed=await api('/admin/activity');setActivities(feed.events)}}
useEffect(()=>{(async()=>{try{let setup=await api('/setup/status');if(!setup.setup){setSetupAvailable(true);setMode(portal==='admin'?'setup':'login');setError(portal==='admin'?'':'First create the store owner account at /admin.');return}setSetupAvailable(false);let me=await api('/me');if(me.user.role!==portal){setMode('login');setError('This account belongs to the '+me.user.role+' panel. Open /'+me.user.role+' instead.');return}setUser(me.user.name);setRole(me.user.role);setView(me.user.role==='staff'?'pos':'dashboard');await refresh();setMode('ready')}catch(e){setMode(e.message.includes('sign in')?'login':'error');setError(e.message)}})()},[]);
async function sign(e){e.preventDefault();setError('');try{setBusy(true);if(mode==='setup'){await api('/setup','POST',{name:owner,password});setSetupAvailable(false);let r=await api('/login','POST',{password});setUser(r.name);setRole('admin');await refresh();setMode('ready');setPassword('');flash('Store owner account created.')}else{if(portal!=='admin'&&!email)throw Error('Enter your '+portal+' account email.');let r=await api(portal==='admin'?'/login':'/account/login','POST',portal==='admin'?{password}:{email,password});if((r.role||'admin')!==portal){await api('/logout','POST');throw Error('This account belongs to the '+r.role+' panel. Open /'+r.role+' instead.')}setUser(r.name);setRole(r.role||'admin');setView(r.role==='staff'?'pos':'dashboard');await refresh();setMode('ready');setPassword('')}}catch(e){setError(e.message)}finally{setBusy(false)}}
async function handleFirebaseIdentity(identity,link=false){if(portal!=='admin')throw Error('Google/mobile sign-in is for linked store owners only.');let token=await identity.getIdToken(),r=await fetch('/api/admin/'+(link?'link':'firebase-login'),{method:'POST',credentials:'same-origin',headers:{authorization:'Bearer '+token,'content-type':'application/json'},body:'{}'}),j=await r.json();if(!r.ok)throw Error(j.error||'Sign-in failed');if(link){setLinkOpen(false);flash('Verified account linked for admin sign-in.')}else{setUser(j.name);setRole('admin');await refresh();setMode('ready');flash('Signed in securely.')}}
async function adminGoogle(link=false){if(!firebaseConfigured){setError('Configure Firebase before enabling Google sign-in.');return}setError('');try{setBusy(true);let result=await signInWithPopup(firebaseAuth,new GoogleAuthProvider());await handleFirebaseIdentity(result.user,link)}catch(e){setError(e.message)}finally{setBusy(false)}}
async function adminPhoneSend(){setError('');try{if(!/^\+[1-9]\d{7,14}$/.test(adminPhone))throw Error('Use a number with country code, e.g. +923001234567');setBusy(true);adminVerifier.current ||= new RecaptchaVerifier(firebaseAuth,'admin-recaptcha',{size:'normal'});setAdminPhoneResult(await signInWithPhoneNumber(firebaseAuth,adminPhone,adminVerifier.current));flash('Verification code sent.')}catch(e){setError(e.message);adminVerifier.current?.clear();adminVerifier.current=null}finally{setBusy(false)}}
async function adminPhoneVerify(link=false){setError('');try{setBusy(true);let result=await adminPhoneResult.confirm(adminCode);await handleFirebaseIdentity(result.user,link);setAdminPhoneResult(null);setAdminCode('')}catch(e){setError(e.message)}finally{setBusy(false)}}
async function loadAccounts(){let r=await api('/accounts');setAccounts(r.accounts)}
async function uploadPicture(productId,file){if(!file)return;setBusy(true);setError('');try{let img=await createImageBitmap(file),scale=Math.min(1,900/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);let blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.82));img.close();if(blob.size>1_000_000)throw Error('Image is too large after resizing');let r=await fetch('/api/products/'+productId+'/image',{method:'POST',body:blob,credentials:'same-origin'}),j=await r.json();if(!r.ok)throw Error(j.error||'Upload failed');await refresh();flash('Product image uploaded.')}catch(e){setError(e.message)}finally{setBusy(false)}}
async function logout(){await api('/logout','POST');setMode('login');setRole('admin');setData(blank);setCart({})}
async function action(path,method,payload,onDone){setBusy(true);setError('');try{let result=await api(path,method,payload);await refresh();onDone?.(result);flash('Saved successfully.');return result}catch(e){setError(e.message);return null}finally{setBusy(false)}}
const product=id=>data.products.find(p=>p.id===id), stock=p=>Number(p.stock_milli||0), inStock=data.products.filter(p=>stock(p)>0), low=data.products.filter(p=>stock(p)<=Number(p.reorder_milli||0));
function open(type,item){setError('');setModal(type);let v=item||model[type]||{};setForm(item?{...v,opening:0,cost:Number(item.cost_paisa)/100,price:Number(item.price_paisa)/100,reorder:Number(item.reorder_milli)/1000,reorderQty:Number(item.reorder_qty_milli)/1000,taxRate:Number(item.tax_rate_bps)/100,packSize:item.pack_size,vendorId:item.vendor_id||'',taxId:item.tax_id||''}:v)}
async function submit(e){e.preventDefault();let type=modal,path={product:'/products',vendor:'/vendors',purchase:'/purchases',adjustment:'/adjustments',expense:'/expenses'}[type],id=form.id;if(id&&(type==='product'||type==='vendor'))path+='/'+id;let result=await action(path,id?'PUT':'POST',form,()=>setModal(null));if(result&&type==='purchase')setView('purchases')}
async function orderAction(id,status){let order=orders.find(o=>o.id===id),transfer=['JazzCash transfer','Easypaisa transfer','Bank transfer'].includes(order?.payment_method),reference='';if(status==='Fulfilled'&&transfer){reference=prompt('Verify the payment in the official merchant/bank account first. Enter its CONFIRMED transaction reference:')?.trim();if(!reference)return}let label=status==='Fulfilled'?'Confirm '+M(order.total_paisa)+' has actually been collected via '+(order.payment_method||'cash')+' and fulfill?':'Cancel this order and release its reserved stock?';if(!confirm(label))return;await action('/orders/'+encodeURIComponent(id)+'/'+status,'POST',status==='Fulfilled'?{paymentCollected:true,verifiedReference:reference}:{})}
function go(v){setView(v);setQuery('');setFilter('all');setSidebar(false);setError('');if(v==='accounts')loadAccounts().catch(e=>setError(e.message));if(v==='pos')setTimeout(()=>scanRef.current?.focus(),80)}
function add(p){if(!p){setError('Barcode / SKU not found. Add this product in inventory first.');return}let next=Number(cart[p.id]||0)+1000;if(next>stock(p)){setError(p.name+' has only '+Q(stock(p))+' in stock.');return}setCart({...cart,[p.id]:next});setError('');setScan('');scanRef.current?.focus()}
function scanAdd(text=scan){let q=text.trim().toLowerCase();if(!q)return;let p=data.products.find(x=>x.barcode?.toLowerCase()===q||x.sku?.toLowerCase()===q);if(!p){let hits=data.products.filter(x=>x.name.toLowerCase().includes(q));if(hits.length===1)p=hits[0]}add(p)}
function updateCart(id,delta){let next=Number(cart[id]||0)+delta,p=product(id);if(next>stock(p)){setError('Not enough stock for '+p.name);return}let c={...cart};if(next<=0)delete c[id];else c[id]=next;setCart(c);setError('')}
let lines=Object.entries(cart).map(([id,qty])=>({p:product(id),qty})).filter(x=>x.p),subtotal=lines.reduce((a,x)=>a+Math.round(x.qty*Number(x.p.price_paisa)/1000),0),discount=Math.round(Number(bill.discount||0)*100),tax=Math.round(Number(bill.tax||0)*100),loyaltyDiscount=Number(bill.redeemPoints||0)/100*5000,total=Math.max(0,subtotal-discount-loyaltyDiscount+tax);
async function loadCustomer(customerId){if(!customerId){setCustomerInfo(null);return}try{setCustomerInfo(await api('/customers/'+encodeURIComponent(customerId)+'/overview'))}catch(e){setError(e.message)}}
async function checkout(){let payload={lines:lines.map(x=>({productId:x.p.id,qty:x.qty/1000})),...bill};let r=await action('/checkout','POST',payload,()=>{setCart({});setBill({payment:'Cash',discount:0,tax:0,customer:'',customerId:'',redeemPoints:0,received:'',note:''})});if(r){setReceipt(r);if(payload.customerId)await loadCustomer(payload.customerId)}}
function printReceipt(r=receipt){let popup=window.open('','_blank','width=430,height=700');if(!popup){flash('Allow popups to print receipt.');return}let esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));popup.document.write(`<!doctype html><html><head><title>Star Mart ${esc(r.receipt)}</title><style>body{font:14px Arial;width:320px;margin:25px auto;color:#222}h1{text-align:center;color:#fa4928;margin-bottom:0}.sub{text-align:center;letter-spacing:2px;font-size:11px}table{width:100%;border-collapse:collapse;margin:20px 0}td{padding:9px 0;border-bottom:1px dashed #ccc}.row{display:flex;justify-content:space-between;padding:5px 0}.total{font-weight:bold;font-size:18px;border-top:2px solid;margin-top:12px;padding-top:12px}</style></head><body><h1>★ Star Mart</h1><div class="sub">HOUSE OF GROCERIES</div><p>${esc(r.receipt)}<br>${esc(date(r.createdAt))}<br>${esc(r.customer)} · ${esc(r.payment)}</p><table>${r.lines.map(x=>`<tr><td>${esc(x.name)}<br>${Q(x.qty)} × ${M(x.unitPrice)}</td><td align="right">${M(x.total)}</td></tr>`).join('')}</table><div class="row"><span>Subtotal</span><b>${M(r.subtotal)}</b></div><div class="row"><span>Discount</span><b>− ${M(r.discount)}</b></div><div class="row"><span>Tax</span><b>${M(r.tax)}</b></div><div class="row total"><span>Total</span><b>${M(r.total)}</b></div><div class="row"><span>Received</span><b>${M(r.received)}</b></div><div class="row"><span>Change</span><b>${M(Number(r.received)-Number(r.total))}</b></div><p style="text-align:center;margin-top:25px">Thank you for shopping!</p></body></html>`);popup.document.close();setTimeout(()=>popup.print(),250)}
async function startCamera(){if(!('BarcodeDetector' in window)||!navigator.mediaDevices?.getUserMedia){setError('Camera scanning is not supported here. Use a USB scanner or enter barcode.');return}try{let formats=await BarcodeDetector.getSupportedFormats(),selected=['ean_13','ean_8','upc_a','upc_e','code_128','code_39'].filter(x=>formats.includes(x));if(!selected.length)throw Error('Barcode format unavailable');let detector=new BarcodeDetector({formats:selected});streamRef.current=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});setCamera(true);setTimeout(async()=>{let v=videoRef.current;if(!v)return;v.srcObject=streamRef.current;await v.play();let last='';timerRef.current=setInterval(async()=>{try{let code=(await detector.detect(v))[0]?.rawValue;if(code&&code!==last){last=code;scanAdd(code)}}catch{}},400)},50)}catch(e){setError(e.message);stopCamera()}}
function stopCamera(){clearInterval(timerRef.current);streamRef.current?.getTracks().forEach(t=>t.stop());streamRef.current=null;setCamera(false)}
useEffect(()=>()=>{clearInterval(timerRef.current);streamRef.current?.getTracks().forEach(t=>t.stop())},[]);
async function uploadLegacy(e){let file=e.target.files?.[0];e.target.value='';if(!file)return;try{let old=JSON.parse(await file.text());if(!confirm('Import this old backup? This works only when the new database has no records.'))return;setBusy(true);let result=await api('/import-legacy','POST',old);await refresh();flash('Imported '+result.products+' products and '+result.sales+' sales.')}catch(ex){setError(ex.message)}finally{setBusy(false)}}
function exportBackup(){let blob=new Blob([JSON.stringify({format:'star-mart-server-export-v1',exportedAt:new Date().toISOString(),...data},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='star-mart-export-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
if(mode==='ready'&&portal==='vendor')return <VendorPanel onLogout={logout}/>;
if(mode==='loading')return <div className="boot">Loading Star Mart…</div>;
if(mode!=='ready')return <div className={'sm-auth sm-portal sm-'+portal}><header className="auth-header"><a href="/shop"><img src="/logo.png" alt="Star Mart"/></a><nav><a href="/shop">Back to store</a></nav></header><main className="sm-auth-scene"><div className="sm-auth-copy"><span className="sm-eyebrow">STAR MART · HOUSE OF GROCERIES</span><h1>{portal==='vendor'?<>Grow your grocery<br/><em>business with us.</em></>:portal==='staff'?<>A smoother day<br/><em>at the counter.</em></>:<>Your store,<br/><em>in clear view.</em></>}</h1><p>{portal==='vendor'?'View your products, stock and sales with your Star Mart vendor account.':portal==='staff'?'Your counter and stock tools are ready when you are.':'Manage grocery stock, customers, vendors and sales in one workspace.'}</p></div><form onSubmit={sign} className="sm-auth-card"><div className="sm-card-mark">✦ {portal.toUpperCase()} ACCESS</div><h2>{mode==='setup'?'Create owner account':mode==='error'?'Connection problem':portal==='admin'?'Owner sign in':portal==='staff'?'Staff sign in':'Vendor sign in'}</h2><p>{mode==='setup'?'Set the store owner name and password.':portal==='vendor'?'Use the login details shared after your application is approved.':portal==='staff'?'Use the staff account created by the owner.':'Enter your owner password to access the admin panel.'}</p>{mode==='setup'&&<label className="sm-field"><span>Your name</span><span className="sm-input"><input value={owner} onChange={e=>setOwner(e.target.value)} required autoComplete="name"/></span></label>}{portal!=='admin'&&mode==='login'&&<label className="sm-field"><span>Email address</span><span className="sm-input"><input type="email" value={email} onChange={e=>setEmail(e.target.value)} required autoComplete="email"/></span></label>}{mode!=='error'&&<label className="sm-field"><span>Password</span><span className="sm-input"><input type="password" value={password} onChange={e=>{setPassword(e.target.value);setError('')}} required minLength={mode==='setup'?6:1} autoComplete={mode==='setup'?'new-password':'current-password'}/></span></label>}{error&&<p className="sm-error" role="alert">{error}</p>}{mode==='error'?<button type="button" className="sm-primary" onClick={()=>location.reload()}>Retry connection</button>:<button className="sm-primary" disabled={busy}>{busy?'Please wait…':mode==='setup'?'Create owner account':'Sign in'} →</button>}{portal==='vendor'&&mode==='login'&&<p className="sm-switch">New supplier? <a href="/become-a-vendor">Become a vendor</a></p>}</form></main></div>;
return <div className="shell"><aside className={'sidebar '+(sidebar?'side-open':'')}><div className="side-top"><img src="/logo.png" alt="Star Mart"/><button className="side-close" onClick={()=>setSidebar(false)} aria-label="Close menu"><X size={20}/></button></div><div className="side-label">STORE WORKSPACE</div><nav>{nav.filter(([key])=>role==='admin'||role==='staff'&&['pos','orders','products'].includes(key)||role==='vendor'&&['products','purchases','vendors'].includes(key)).map(([key,label,Icon])=><button key={key} onClick={()=>go(key)} className={view===key?'active':''}><Icon size={19}/><span>{label}</span>{key==='products'&&low.length>0&&<em>{low.length}</em>}</button>)}</nav><div className="side-footer"><div className="profile"><span>{user.slice(0,1).toUpperCase()}</span><div><strong>{user}</strong><small>{portal==='admin'?'Store administrator':portal==='staff'?'Store staff':'Vendor portal'}</small></div></div><button onClick={logout}><LogOut size={17}/> Sign out</button></div></aside><div className="work"><header className="topbar"><div className="top-left"><button className="hamburger" onClick={()=>setSidebar(true)} aria-label="Open menu"><Menu size={22}/></button><div><small>STAR MART / OPERATIONS</small><strong>{nav.find(n=>n[0]===view)?.[1]}</strong></div></div><div className="top-right"><span className="date-pill"><CalendarDays size={16}/>{new Date().toLocaleDateString('en-PK',{day:'numeric',month:'short',year:'numeric'})}</span><IconButton icon={RefreshCw} className="quiet" onClick={()=>refresh().catch(e=>setError(e.message))}>Refresh</IconButton>{role==='admin'&&firebaseConfigured&&<button className="quiet" onClick={()=>{setError('');setLinkOpen(true)}}>Link sign-in</button>}{role==='admin'&&<label className="quiet upload-label"><Upload size={17}/>Import old backup<input type="file" accept=".json,application/json" hidden onChange={uploadLegacy}/></label>}<a className="quiet shop-admin-link" href="/shop" target="_blank" rel="noopener noreferrer"><ShoppingBag size={17}/>View shop</a>{role==='admin'&&<IconButton icon={Download} className="quiet" onClick={exportBackup}>Export</IconButton>}</div></header><main className="main"><div className="page-header"><div><span className="eyebrow">{view==='dashboard'?'STORE OVERVIEW':view==='pos'?'COUNTER BILLING':'STORE OPERATIONS'}</span><h1>{({dashboard:'A clear view of your store.',pos:'Point of sale.',products:'Product inventory.',orders:'Customer orders.',purchases:'Purchase register.',sales:'Sales & receipts.',vendors:'Supplier directory.',adjustments:'Stock adjustments.',expenses:'Business expenses.',reports:'Reports & insights.',accounts:'Team accounts.'})[view]}</h1><p>{({dashboard:'Track every item, rupee and reorder point.',pos:'Scan a barcode, prepare the bill and collect payment.',products:'Every product, price, barcode and shelf in one place.',orders:'Review pickup and delivery requests; release or fulfill stock.',purchases:'Record received stock with invoice, vendor and expiry.',sales:'Every checkout line and its receipt.',vendors:'Supplier contacts and payment terms.',adjustments:'Explain every stock correction and loss.',expenses:'Keep operating expenses visible.',reports:'Figures calculated from recorded transactions.',accounts:'Create staff and vendor access with limited permissions.'})[view]}</p></div>{view==='dashboard'&&role!=='vendor'?<IconButton icon={ScanBarcode} className="primary" onClick={()=>go('pos')}>Open POS</IconButton>:(role==='admin'?['products','vendors','purchases','adjustments','expenses']:role==='staff'?['adjustments']:[]).includes(view)?<IconButton icon={Plus} className="primary" onClick={()=>open(({products:'product',vendors:'vendor',purchases:'purchase',adjustments:'adjustment',expenses:'expense'})[view])}>Add {({products:'product',vendors:'vendor',purchases:'purchase',adjustments:'adjustment',expenses:'expense'})[view]}</IconButton>:null}</div>
{error&&!modal&&<div className="error banner"><AlertTriangle size={17}/>{error}<button onClick={()=>setError('')} aria-label="Dismiss"><X size={16}/></button></div>}
{view==='dashboard'&&role==='admin'&&<Dashboard data={data}low={low}go={go}stock={stock}/>}
{view==='activity'&&role==='admin'&&<DataTable title="Store activity · latest 150 changes" count={activities.length} columns={['When','Action','Source','Record','ID']} rows={activities.map(e=><tr key={e.id}><td>{date(e.created_at)}</td><td><strong>{e.action}</strong></td><td>{e.actor}</td><td>{e.entity.replaceAll('_',' ')}</td><td><small>{e.entity_id}</small></td></tr>)}/>}
{view==='pos'&&<div className="pos-grid"><div className="pos-left"><section className="card scan-card"><div className="card-title"><div><span className="eyebrow">BARCODE STATION</span><h2>Scan or search</h2></div><ScanBarcode size={26} color="#f15a31"/></div><div className="scan-input"><ScanBarcode size={19}/><input ref={scanRef} value={scan} onChange={e=>setScan(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'){e.preventDefault();scanAdd()}}} placeholder="Scan barcode / SKU, then Enter" autoFocus/><button onClick={()=>scanAdd()}>Add</button></div><div className="scan-help">USB scanners type into this field. Set the scanner suffix to Enter.</div><div className="scan-tools"><button onClick={camera?stopCamera:startCamera}><Camera size={17}/>{camera?'Stop camera':'Use camera'}</button><button onClick={()=>scanRef.current?.focus()}><ScanBarcode size={17}/>Focus scanner</button></div>{camera&&<video ref={videoRef} className="camera-video" muted playsInline/>}</section><section className="card catalog-card"><div className="card-title"><div><span className="eyebrow">PRODUCT CATALOG</span><h2>Quick add</h2></div><span className="count-pill">{inStock.length} available</span></div><div className="search-field"><Search size={18}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search name, brand, category, barcode"/></div><div className="catalog-list">{inStock.filter(p=>(p.name+' '+p.barcode+' '+p.sku+' '+p.category+' '+p.brand).toLowerCase().includes(search.toLowerCase())).slice(0,40).map(p=><button className="catalog-row" key={p.id} onClick={()=>add(p)}><span className="product-avatar"><Package size={21}/></span><span className="catalog-name"><strong>{p.name}</strong><small>{p.category||'Grocery'} · {p.barcode||p.sku||'No barcode'} · {Q(stock(p))} left</small></span><b>{M(p.price_paisa)}</b><Plus size={17}/></button>)}{!inStock.length&&<Empty text="Add products and receive stock to start billing."/>}</div></section></div><section className="card checkout-card"><div className="card-title"><div><span className="eyebrow">CURRENT TRANSACTION</span><h2>Bill details <span className="count-pill">{lines.reduce((n,x)=>n+x.qty/1000,0)} items</span></h2></div><button className="text-btn" onClick={()=>setCart({})}>Clear</button></div><div className="bill-lines">{lines.map(({p,qty})=><div className="bill-line" key={p.id}><div><strong>{p.name}</strong><small>{M(p.price_paisa)} each</small></div><div className="stepper"><button onClick={()=>updateCart(p.id,-1000)}><Minus size={14}/></button><span>{Q(qty)}</span><button onClick={()=>updateCart(p.id,1000)}><Plus size={14}/></button></div><b>{M(Math.round(qty*Number(p.price_paisa)/1000))}</b></div>)}{!lines.length&&<div className="bill-empty"><ShoppingBag size={35}/><strong>Ready for the first item</strong><span>Scan a product or use quick add.</span></div>}</div><div className="bill-form"><label>Registered customer<select value={bill.customerId||''} onChange={e=>{let id=e.target.value,c=customers.find(x=>x.id===id);setBill({...bill,customerId:id,customer:c?.name||'',redeemPoints:0});loadCustomer(id)}}><option value="">Walk-in (no account)</option>{customers.map(c=><option key={c.id} value={c.id}>{c.name} · {c.email}</option>)}</select></label><label>Customer name<input value={bill.customer} onChange={e=>setBill({...bill,customer:e.target.value})} placeholder="Walk-in customer"/></label>{bill.customerId&&customerInfo&&<div className="pos-loyalty"><strong>{customerInfo.summary.points} points available</strong><span>Credit due: {M(customerInfo.summary.outstandingPaisa)}</span><label>Redeem points<select value={bill.redeemPoints||0} onChange={e=>setBill({...bill,redeemPoints:Number(e.target.value)})}>{Array.from({length:Math.min(2,Math.floor(Math.max(0,customerInfo.summary.points)/100)+1)},(_,i)=><option key={i} value={i*100}>{i?i*100+' points · Rs '+i*50+' off':'No points'}</option>)}</select></label><small>Next bill only · Rs 3,000 minimum · one Rs 50 reward · cannot combine discounts · margin check at checkout.</small></div>}<label>Payment method<select value={bill.payment} onChange={e=>setBill({...bill,payment:e.target.value})}>{['Cash','Card','Bank transfer','Credit'].map(x=><option key={x}>{x}</option>)}</select></label><label>Discount (Rs)<input type="number" min="0" step="0.01" value={bill.discount} onChange={e=>setBill({...bill,discount:e.target.value})}/></label><label>Tax (Rs)<input type="number" min="0" step="0.01" value={bill.tax} onChange={e=>setBill({...bill,tax:e.target.value})}/></label><label>Received (Rs)<input type="number" min="0" step="0.01" value={bill.received} onChange={e=>setBill({...bill,received:e.target.value})} placeholder="Exact amount"/></label><label>Reference<input value={bill.note} onChange={e=>setBill({...bill,note:e.target.value})} placeholder="Optional"/></label></div><div className="totals"><div><span>Subtotal</span><b>{M(subtotal)}</b></div><div><span>Discount</span><b>− {M(discount)}</b></div>{loyaltyDiscount>0&&<div><span>Points reward</span><b>− {M(loyaltyDiscount)}</b></div>}<div><span>Tax</span><b>{M(tax)}</b></div><div className="grand"><span>Amount due</span><b>{M(total)}</b></div><div><span>Change</span><b>{M(Math.max(0,Math.round(Number(bill.received||0)*100)-total))}</b></div></div><button className="primary full" disabled={busy||!lines.length} onClick={checkout}><CircleCheck size={18}/>Complete sale</button><p className="checkout-note">Stock is checked again on the server before the sale is saved.</p>{bill.customerId&&<CreditCollection customerId={bill.customerId} info={customerInfo} reload={()=>loadCustomer(bill.customerId)} flash={flash} setError={setError}/>}</section></div>}
{view==='orders'&&<DataTable title="Customer orders" count={orders.length} columns={['Order / date','Customer','Items','Fulfillment','Total','Status','Action']} rows={orders.map(o=><tr key={o.id}><td><strong>{o.id}</strong><small>{date(o.created_at)}</small></td><td>{o.customer_name}<small>{o.customer_phone} · {o.customer_email||'No email'}</small></td><td>{o.items.map(i=>i.name+' × '+Q(i.qty_milli)).join(', ')}</td><td>{o.fulfillment}<small>{o.address||'In-store pickup'}</small><small>{o.payment_method||'Cash'} · {o.payment_status||'Awaiting collection'}</small>{o.payment_reference&&<small>Submitted: {o.payment_reference}</small>}{o.verified_reference&&<small>Verified: {o.verified_reference}</small>}</td><td><strong>{M(o.total_paisa)}</strong></td><td><Badge warn={o.status==='Pending'}>{o.status}</Badge></td><td>{o.status==='Pending'?<div className="order-actions"><button onClick={()=>orderAction(o.id,'Fulfilled')}>Payment collected · fulfill</button><button onClick={()=>orderAction(o.id,'Cancelled')}>Cancel</button></div>:'—'}</td></tr>)}/>}
{view==='products'&&role==='admin'&&<SampleCleanup onDone={refresh}/>}
{view==='products'&&<DataTable title="All products" count={data.products.length} search={query} setSearch={setQuery} filter={filter} setFilter={setFilter} filters={['all','low','available']} columns={role==='staff'?['Product','SKU / Barcode','Category / Shelf','In stock','Reorder','Sell price','']:['Product','SKU / Barcode','Category / Shelf','In stock','Reorder','Cost','Sell price','']} rows={data.products.filter(p=>(p.name+' '+p.sku+' '+p.barcode+' '+p.brand).toLowerCase().includes(query.toLowerCase())).filter(p=>filter==='low'?low.includes(p):filter==='available'?stock(p)>0:true).map(p=><tr key={p.id}><td><span className="product-mini">{p.image&&<img src={p.image} alt=""/>}<strong>{p.name}</strong></span><small>{p.brand} {p.pack_size} · {p.unit}</small></td><td>{p.sku||'—'}<small>{p.barcode||'No barcode'}</small></td><td>{p.category||'—'}<small>{p.location||'No shelf'}</small></td><td><Badge warn={stock(p)<=Number(p.reorder_milli)}>{Q(stock(p))}</Badge></td><td>{Q(p.reorder_milli)}</td>{role!=='staff'&&<td>{M(p.cost_paisa)}</td>}<td><strong>{M(p.price_paisa)}</strong></td><td>{role==='admin'&&<><button className="text-btn" onClick={()=>open('product',p)}>Edit</button><label className="text-btn picture-button">Image<input type="file" accept="image/jpeg,image/png,image/webp" hidden onChange={e=>{uploadPicture(p.id,e.target.files?.[0]);e.target.value=''}}/></label></>}</td></tr>)}/>}
{view==='purchases'&&<DataTable title="Stock received" count={data.purchases.length} columns={['Date','Product','Vendor','Quantity','Batch / Expiry','Unit cost','Total','Payment']} rows={data.purchases.map(x=><tr key={x.id}><td>{date(x.created_at)}<small>{x.invoice||'No invoice'}</small></td><td><strong>{product(x.product_id)?.name||'Historical product'}</strong></td><td>{data.vendors.find(v=>v.id===x.vendor_id)?.name||'—'}</td><td>{Q(x.qty_milli)}</td><td>{x.batch||'—'}<small>{x.expiry?String(x.expiry).slice(0,10):'No expiry'}</small></td><td>{M(x.unit_cost_paisa)}</td><td><strong>{M(Math.round(Number(x.qty_milli)*Number(x.unit_cost_paisa)/1000))}</strong></td><td><Badge warn={x.payment==='Unpaid'}>{x.payment}</Badge><small>Paid now: {M(x.payment==='Paid'?Math.round(Number(x.qty_milli)*Number(x.unit_cost_paisa)/1000):x.paid_paisa)}</small></td></tr>)}/>}
{view==='sales'&&<DataTable title="Sales line items" count={data.sales.length} columns={['Date / receipt','Product','Quantity','Unit price','Line total','Customer','Payment']} rows={data.sales.map(x=><tr key={x.id}><td>{date(x.created_at)}<small>{x.receipt}</small></td><td><strong>{product(x.product_id)?.name||'Historical product'}</strong></td><td>{Q(x.qty_milli)}</td><td>{M(x.unit_price_paisa)}</td><td><strong>{M(x.line_total_paisa)}</strong></td><td>{x.customer}</td><td>{x.payment}</td></tr>)}/>}
{view==='bulk'&&role==='admin'&&<BulkImport onImported={refresh}/>}
{view==='customers'&&role==='admin'&&<DataTable title="Registered customers" count={customers.length} columns={['Customer','Email','Phone','Shopping','Credit due','Points']} rows={customers.map(c=>{return <tr key={c.id}><td><strong>{c.name}</strong></td><td>{c.email}</td><td>{c.phone||'—'}</td><td>{c.bill_count} bills · {M(c.total_spend_paisa)}</td><td>{M(c.outstanding_paisa)}</td><td><strong>{c.points}</strong><button className="text-btn" onClick={()=>{setBill(b=>({...b,customerId:c.id,customer:c.name}));go('pos');loadCustomer(c.id)}}>Open POS →</button></td></tr>})}/>}
{view==='vendors'&&role==='admin'&&<VendorManagement vendors={data.vendors} purchases={data.purchases} onApproved={async()=>{await refresh();await loadAccounts()}}/>}{view==='vendors'&&<DataTable title="Supplier contacts" count={data.vendors.length} columns={['Vendor','Phone','Email','Address','Terms','Tax ID','']} rows={data.vendors.map(x=><tr key={x.id}><td><strong>{x.name}</strong><small>{x.contact||'No contact person'}</small></td><td>{x.phone||'—'}</td><td>{x.email||'—'}</td><td>{x.address||'—'}</td><td>{x.terms||'—'}</td><td>{x.tax_id||'—'}</td><td>{role==='admin'&&<button className="text-btn" onClick={()=>open('vendor',x)}>Edit</button>}</td></tr>)}/>}
{view==='adjustments'&&<DataTable title="Stock movement corrections" count={data.adjustments.length} columns={['Date','Product','Reason','Change','Explanation']} rows={data.adjustments.map(x=><tr key={x.id}><td>{date(x.created_at)}</td><td><strong>{product(x.product_id)?.name||'Historical product'}</strong></td><td>{x.reason}</td><td><Badge warn={Number(x.qty_milli)<0}>{Number(x.qty_milli)>0?'+':''}{Q(x.qty_milli)}</Badge></td><td>{x.note}</td></tr>)}/>}
{view==='expenses'&&<DataTable title="Operating costs" count={data.expenses.length} columns={['Date','Category','Description','Amount','Payment','Reference']} rows={data.expenses.map(x=><tr key={x.id}><td>{date(x.created_at)}</td><td>{x.category}</td><td><strong>{x.description}</strong></td><td><strong>{M(x.amount_paisa)}</strong></td><td>{x.payment}</td><td>{x.reference||'—'}</td></tr>)}/>}
{view==='accounts'&&role==='admin'&&<section className="card account-section"><div className="card-title"><div><span className="eyebrow">ACCESS CONTROL</span><h2>Team accounts</h2></div></div><p>Create staff access here. Customers sign up on the store. Vendor applications and approvals are in Vendors.</p><form className="account-form" onSubmit={async e=>{e.preventDefault();let r=await action('/accounts','POST',accountForm);if(r){setAccountForm({role:'staff'});loadAccounts()}}}><label>Name<input required value={accountForm.name||''} onChange={e=>setAccountForm({...accountForm,name:e.target.value})}/></label><label>Email<input type="email" required value={accountForm.email||''} onChange={e=>setAccountForm({...accountForm,email:e.target.value})}/></label><label>Password (6+ characters)<input type="password" required minLength={6} value={accountForm.password||''} onChange={e=>setAccountForm({...accountForm,password:e.target.value})}/></label><button className="primary" disabled={busy}>Create account</button></form><div className="account-list">{accounts.map(a=><div key={a.id}><strong>{a.name}</strong><span>{a.email} · {a.role}{a.role==='vendor'?' · '+(data.vendors.find(v=>v.id===a.vendor_id)?.name||'Vendor'):''}</span><button className="quiet" onClick={async()=>{await action('/accounts/'+a.id,'PATCH',{active:!a.active});loadAccounts()}}>{a.active?'Disable':'Enable'}</button></div>)}</div></section>}
{view==='reports'&&<Reports data={data}low={low}stock={stock}product={product}/>}
</main></div>{toast&&<div className="toast"><CircleCheck size={17}/>{toast}</div>}
{modal&&<div className="overlay" onMouseDown={e=>{if(e.target===e.currentTarget)setModal(null)}}><form className="modal" onSubmit={submit}><div className="modal-head"><div><span className="eyebrow">STAR MART / NEW RECORD</span><h2>{form.id?'Edit':'Add'} {modal}</h2></div><button type="button" onClick={()=>setModal(null)} aria-label="Close"><X size={20}/></button></div><div className="modal-fields">{fields[modal].filter(([key])=>!(form.id&&modal==='product'&&key==='opening')).map(([key,label,type='text',required=false,options])=><label key={key}>{label}{required&&' *'}{type==='select'?<select required={required} value={form[key]??options[0]} onChange={e=>setForm({...form,[key]:e.target.value})}>{options.map(x=><option key={x}>{x}</option>)}</select>:type==='product'||type==='vendor'?<select required={required} value={form[key]??''} onChange={e=>{let v=e.target.value;setForm({...form,[key]:v,...(key==='productId'&&modal==='purchase'?{cost:Number(product(v)?.cost_paisa||0)/100}:{})})}}><option value="">{type==='product'?'Select product':'No vendor selected'}</option>{(type==='product'?data.products:data.vendors).map(x=><option value={x.id} key={x.id}>{x.name}{type==='product'?' ('+Q(stock(x))+' in stock)':''}</option>)}</select>:<input type={type} step={type==='number'?'0.001':undefined} required={required} value={form[key]??''} onChange={e=>setForm({...form,[key]:e.target.value})} placeholder={key==='change'?'e.g. -2 or 3':''}/>}</label>)}</div>{error&&<div className="error">{error}</div>}<div className="modal-foot"><button type="button" className="quiet" onClick={()=>setModal(null)}>Cancel</button><button className="primary" disabled={busy}>{busy?'Saving…':'Save record'}</button></div></form></div>}
{linkOpen&&<div className="overlay" onMouseDown={e=>{if(e.target===e.currentTarget)setLinkOpen(false)}}><div className="receipt-modal admin-link-modal"><h2>Link admin sign-in</h2><p>Only the current owner can link a verified Google or mobile account. Once linked, it can sign in without the owner password.</p><button className="quiet" onClick={()=>adminGoogle(true)}>Link Google account</button><label>Mobile number<input value={adminPhone} onChange={e=>setAdminPhone(e.target.value)} placeholder="+923001234567"/></label><div id="admin-recaptcha"/>{adminPhoneResult?<><input value={adminCode} onChange={e=>setAdminCode(e.target.value)} placeholder="SMS code"/><button className="quiet" onClick={()=>adminPhoneVerify(true)}>Verify and link mobile</button></>:<button className="quiet" onClick={adminPhoneSend}>Send mobile code</button>}{error&&<div className="error">{error}</div>}<button className="quiet" onClick={()=>setLinkOpen(false)}>Close</button></div></div>}
{receipt&&<div className="overlay"><div className="receipt-modal"><CircleCheck size={38} color="#149773"/><h2>Sale completed</h2><p>Receipt <strong>{receipt.receipt}</strong> · {M(receipt.total)}</p><div className="receipt-actions"><IconButton icon={Printer} className="primary" onClick={()=>printReceipt()}>Print receipt</IconButton><button className="quiet" onClick={()=>{setReceipt(null);scanRef.current?.focus()}}>Next customer</button></div></div></div>}</div>}
function Badge({children,warn}){return <span className={'badge '+(warn?'warn':'')}>{children}</span>}
function Empty({text}){return <div className="empty"><Package size={30}/><span>{text||'No records yet. Add your first entry to get started.'}</span></div>}
function DataTable({title,count,columns,rows,search,setSearch,filter,setFilter,filters}){return <section className="card table-card"><div className="table-top"><div><h2>{title}</h2><span>{count} records</span></div>{setSearch&&<div className="table-controls"><div className="search-field"><Search size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search products or barcode"/></div><select value={filter} onChange={e=>setFilter(e.target.value)}>{filters.map(x=><option key={x} value={x}>{x==='all'?'All stock':x==='low'?'Low stock':'Available'}</option>)}</select></div>}</div><div className="table-scroll"><table><thead><tr>{columns.map((c,i)=><th key={i}>{c}</th>)}</tr></thead><tbody>{rows.length?rows:<tr><td colSpan={columns.length}><Empty/></td></tr>}</tbody></table></div></section>}
function Dashboard({data,low,go,stock}){let today=new Date().toDateString(),todaySales=data.receipts.filter(x=>new Date(x.created_at).toDateString()===today).reduce((n,x)=>n+Number(x.total_paisa),0),value=data.products.reduce((n,p)=>n+Math.round(stock(p)*Number(p.cost_paisa)/1000),0),revenue=data.receipts.reduce((n,x)=>n+Number(x.total_paisa),0),expenses=data.expenses.reduce((n,x)=>n+Number(x.amount_paisa),0),unpaid=data.purchases.filter(x=>x.payment==='Unpaid').reduce((n,x)=>n+Math.round(Number(x.qty_milli)*Number(x.unit_cost_paisa)/1000),0),sold=new Map();data.sales.forEach(x=>sold.set(x.product_id,(sold.get(x.product_id)||0)+Number(x.qty_milli)));let ranked=[...sold].sort((a,b)=>b[1]-a[1]).slice(0,5);let metrics=[['Today’s sales',M(todaySales),'Recorded today',Wallet,'green'],['Stock at cost',M(value),'Current quantity × cost',Boxes,'blue'],['Low stock items',low.length,'At or below reorder level',AlertTriangle,'orange'],['Total sales',M(revenue),'All completed receipts',ShoppingBag,'violet']];return <><div className="metric-grid">{metrics.map(([name,val,desc,Icon,tone])=><article className="metric-card" key={name}><div className="metric-head"><span>{name}</span><div className={'metric-icon '+tone}><Icon size={21}/></div></div><strong>{val}</strong><small>{desc}</small></article>)}</div><div className="insight-strip"><span><b>{data.products.length}</b> products</span><span><b>{Q(data.products.reduce((n,p)=>n+stock(p),0))}</b> units in stock</span><span><b>{M(unpaid)}</b> supplier invoices marked unpaid</span><span><b>{M(expenses)}</b> recorded expenses</span></div><div className="two-cols"><section className="card"><div className="card-title"><div><span className="eyebrow">ACTION NEEDED</span><h2>Reorder watchlist</h2></div><button className="text-btn" onClick={()=>go('products')}>View inventory <ChevronRight size={16}/></button></div>{low.length?low.slice(0,6).map(p=><div className="watch-row" key={p.id}><span className="product-avatar"><Package size={20}/></span><div><strong>{p.name}</strong><small>Reorder at {Q(p.reorder_milli)} {p.unit}</small></div><Badge warn>{Q(stock(p))} left</Badge></div>):<Empty text="Stock levels are above their reorder points."/>}</section><section className="card"><div className="card-title"><div><span className="eyebrow">LATEST ACTIVITY</span><h2>Recent receipts</h2></div><button className="text-btn" onClick={()=>go('sales')}>All sales <ChevronRight size={16}/></button></div>{data.receipts.length?data.receipts.slice(0,6).map(r=><div className="activity-row" key={r.id}><div className="activity-icon"><ArrowUpRight size={17}/></div><div><strong>{r.id}</strong><small>{r.customer} · {date(r.created_at)}</small></div><b>{M(r.total_paisa)}</b></div>):<Empty text="Completed sales will appear here."/>}</section></div><div className="two-cols"><section className="card"><div className="card-title"><div><span className="eyebrow">PRODUCT PERFORMANCE</span><h2>Best sellers</h2></div></div>{ranked.length?ranked.map(([id,qty],i)=><div className="rank-row" key={id}><span>{String(i+1).padStart(2,'0')}</span><strong>{data.products.find(p=>p.id===id)?.name||'Historical item'}</strong><b>{Q(qty)} sold</b></div>):<Empty text="Product rankings start after the first sale."/>}</section><section className="card"><div className="card-title"><div><span className="eyebrow">STORE PULSE</span><h2>Operations snapshot</h2></div></div>{[['Out of stock',data.products.filter(p=>stock(p)<=0).length],['Vendors',data.vendors.length],['Purchase entries',data.purchases.length],['Stock corrections',data.adjustments.length]].map(([label,n])=><div className="pulse-row" key={label}><span>{label}</span><b>{n}</b></div>)}</section></div></>}
function Reports({data,low,stock,product}){let inventory=data.products.reduce((n,p)=>n+Math.round(stock(p)*Number(p.cost_paisa)/1000),0),sales=data.sales.reduce((n,x)=>n+Number(x.line_total_paisa),0),cogs=data.sales.reduce((n,x)=>n+Math.round(Number(x.qty_milli)*Number(x.cost_at_sale_paisa)/1000),0),expenses=data.expenses.reduce((n,x)=>n+Number(x.amount_paisa),0),expiring=data.purchases.filter(x=>x.expiry&&new Date(x.expiry).getTime()-Date.now()<=30*864e5);let summary=[['Stock valuation',inventory,'At last recorded cost'],['Sales revenue',sales,'Completed sales, net of discounts plus tax'],['Estimated gross margin',sales-cogs,'Revenue minus recorded item cost'],['Expenses',expenses,'Recorded operating costs'],['Estimated result',sales-cogs-expenses,'Before unrecorded costs and tax obligations']];return <><div className="report-grid">{summary.map(([label,n,desc])=><article className="report-card" key={label}><span>{label}</span><strong>{M(n)}</strong><small>{desc}</small></article>)}</div><div className="two-cols"><section className="card"><div className="card-title"><div><span className="eyebrow">REORDER</span><h2>Items to buy</h2></div></div>{low.length?low.map(p=><div className="watch-row" key={p.id}><span className="product-avatar"><Package size={18}/></span><div><strong>{p.name}</strong><small>{p.location||'No shelf'} · reorder {Q(p.reorder_qty_milli)}</small></div><Badge warn>{Q(stock(p))} / {Q(p.reorder_milli)}</Badge></div>):<Empty text="Nothing needs reordering."/>}</section><section className="card"><div className="card-title"><div><span className="eyebrow">DATE TRACKING</span><h2>Expiring purchase batches</h2></div></div>{expiring.length?expiring.slice(0,15).map(x=><div className="watch-row" key={x.id}><span className="product-avatar"><CalendarDays size={18}/></span><div><strong>{product(x.product_id)?.name||'Product'} · {x.batch||'No batch'}</strong><small>Purchased {Q(x.qty_milli)} · expiry {String(x.expiry).slice(0,10)}</small></div><Badge warn>Check</Badge></div>):<Empty text="No dated purchases expiring in 30 days."/>}<p className="report-foot">Expiry is based on purchase dates. Sales are not allocated to individual batches; verify remaining quantities physically.</p></section></div><p className="report-foot">These are management estimates. Purchase invoices marked part paid have no outstanding balance calculation until actual payments are recorded.</p></>}
const path=location.pathname.replace(/\/$/,'')||'/';createRoot(document.getElementById('root')).render(path==='/account'?<CustomerDashboard/>:path==='/signup'||path==='/login'?<CustomerAuth initialMode={path==='/login'?'login':'signup'}/>:path==='/become-a-vendor'?<VendorApply/>:['/', '/shop'].includes(path)?<Shop initialSignup={false}/>:<App portal={path==='/staff'?'staff':path==='/vendor'?'vendor':'admin'}/>);
